"""Reconcile existing research archives before copying exact served XML."""
import hashlib, json, re, xml.etree.ElementTree as E
from pathlib import Path
slugs = ['sandpile','ising','sand','solid-diffusion','interstitial-diffusion','heat-diffusion','crystallization-basic','dla']
inv=json.loads(Path('experiments/catalog/inventory.json').read_text())
selection=json.loads(Path('experiments/catalog/selection/selection.json').read_text())
tree={r['path']:r for r in json.loads(Path('experiments/catalog/pinned/galapagos-tree.json').read_text())['tree']}
notes={
'sandpile': 'Hard 101×101 lattice. Setup random draws integer 0..3; setup-uniform uses grains-per-patch=1. Drop defaults random; center and mouse-click are alternatives. go adds one grain then stabilizes complete avalanche before one tick. Each stabilization round snapshots overloaded membership, subtracts exactly FOUR (despite misleading Info saying all grains), adds one to each existing faces neighbor; missing edge neighbors lose grains. Next active membership is neighbors of overloaded sites, not a global rescan. Lifetime counts nonempty overload rounds; size is unique fired sites. No terminal condition. Explore pushes/restores n without ticking, but source restores first with but-last (one-element stack normally). total-on-tick remains zero after setup while total and plot are initialized. Record positive avalanche sizes/lifetimes only; log histogram refresh every 100 ticks. Clear data does not reset pile/tick. Animation is presentation timing, not a new phase.',
'ising': 'Wrapped 81×81 lattice. Setup independent random integer100 < probability-of-spin-up=90, spin ±1. go performs 1000 choices WITH replacement and immediate sequential updates, then advances attempted-flip ticks by 1000. Ediff=2*spin*sum(neighbors4.spin); accept Ediff<=0, else only temperature>0 and uniform<exp(-Ediff/temperature). Temperature default 2. Zero temperature never attempts exponential draw for uphill flips. sum-of-spins updated by twice NEW spin; magnetization=sum/count. No terminal condition. Probability only affects setup; temperature is live. Plot magnetization by attempted flips.',
'sand': '81×81, x wraps, y hard. Setup gray floor y < -0.8*maxPycor; blue spouts y=round(.9*maxPycor), x mod round(.6*maxPxcor)=0. Tick starts at zero. go spouts when ticks mod spacing=0 (default3) with uniform100 <= release-chance(default100), then move-all-sand then tick. Snapshot pcolor into next-color; all brown decisions read OLD pcolor; commit only after all decisions. Down black wins; else lower-left brown/right black -> right; inverse -> left; both black -> random side. Other colors do not count as brown support. Competing writes may coalesce grains; conservation is NOT promised. dump-sand overlays brown with density(default10) between floor and spout, without clearing existing sand/ticking. No stop. Info density25 differs from actual widget10.',
'solid-diffusion': 'Hard 35×35 lattice. Setup one green Agent each x<0 and blue each x>0, vacancy column x=0. go snapshots vacancies, asks them in random order to choose one atom from faces-neighbor occupancy and move into vacancy immediately, then tick. A newly opened vacancy is not added to the snapshot; the same atom can move more than once. Count and species conserved, one occupancy per site. Report greens/blues by column and (rightmost green x - leftmost blue x)^2, not individual displacement or MSD. No parameters or stop in original.',
'interstitial-diffusion': '41×201 patch lattice, x hard, y wraps; native x0..40,y-200..0 adapted by coordinate translation only. Lattice markers at patch+(0.5,0.5), x<max; diffusing Agents initially x<=min+10 inclusive with Bernoulli concentration .8. Both constant surfaces default false; left concentration .7,right0. simulate preflight stops ticks>=max-ticks(default1000). Snapshot d-atoms random order, four headings equally probable INCLUDING failed off-world attempts; move only into empty d-atom site; occupancy sees preceding moves. Reapply enabled Bernoulli boundary surfaces after movement, calculate columns/count/world-height then tick. Source graph/drawing agents are presentation; canonical physical atoms remain World Agents. draw-profile hides lattice, edits one column with up-to-n-of(worldHeight*rounded concentration) atoms, resets tick and plot setup, no simulation step. Current, initial(tick0), and tick15 profiles are distinct. Lattice visibility and go-mode are native actions; no invented units.',
'heat-diffusion': 'Wrapped 51×51 patch lattice. plate-size=round(.6*maxPxcor)=15. Initial interior |x|,|y|<15 uses44; boundary strips left1,right/top/bottom50; corner quadrants average incident boundaries. old-temperature initialized before decorative legend mutates temperature only. go asks patches RANDOM SEQUENTIALLY: temperature=d*sum(neighbors4.old)+(1-4d)*old, clamp edges, immediately old=temperature. This is NOT a simultaneous Euler Grid.diffuse call; later patches see earlier old writes. d=.25*exp(-1/(alpha+.3)), alpha=.8418. update-alpha explicitly selects wood .00128,stone .012,iron .2034,aluminum .8418,silver1.7004; other keeps manually supplied alpha. Live edge changes clamp on next go, initial temp is setup only. Legend is presentation; record any omission/adaptation. No terminal condition or native plots.',
'crystallization-basic': 'Hard 33×33 lattice, initial rectangle width/height31 with STRICT |x|<width/2,|y|<height/2 (31×31 atoms); circle toggle uses Euclidean radius width/2. Agents own temp1550 and heading. Cached neighboring-turtles includes self plus Moore sites; sides-exposed=9-count. go preflight max(temp)<melting550 stops WITHOUT tick. Reset num-frozen; randomized sequential cool-turtles uses (sum(neighboring temps)+room100*sidesExposed+own temp)/10, own twice, preceding writes visible. Separate color phase then separate rotate phase. temp-range=(initial-melting)/7 frozen at setup; color index floor((temp-melting)/range)+1; only index<0 increments num-frozen (NOT simply temp<melting). Liquid temp>=melting copies a random neighbor with temp<=melting (may include self at equality), otherwise random turn. Average after full phase then tick. Histograms are current color bins; num-frozen history uses source threshold. No latent heat, physical units or empirical validation inferred.',
'dla': 'Hard 171×171 lattice. Setup center green, radius0, zero walkers,tick0. go preflight radius>=maxPxcor-3 stops. Birth while count<max-particles100 AND count<ticks (first go births none). Random heading at creation, jump radius+1.5 or maxPxcor85 (use-whole-world default true), then turn180 toward center. Snapshot walkers random sequential: wander turns by U(wiggle60)-U(wiggle60), dies if cannot move1; otherwise forward1. If ANY Moore neighbor is green, mark current patch green, radius=max(radius, continuous distance of walker), die. Later walkers see newly deposited patches. With whole-world false kill beyond radius+3 after sticking check. tick only after completed go; parameters live. Radius uses continuous position, not patch-center distance; no seed/trajectory identity with NetLogo.'}
report=['# Selected materials exact served source audit','',f"Inventory Galapagos revision `{inv['upstream']['galapagos']}`. Archived research originals copied only after SHA-256, byte count and pinned Git blob match. Desktop membership is not Web catalog membership. No new literature pass.",'']
evidence=[]
for slug in slugs:
 row=next(r for r in inv['rows'] if r.get('scope',{}).get('experimentSlug')==slug)
 data=(Path('docs/research/netlogo-web/evidence/physics')/(slug+'.nlogox')).read_bytes()
 sha=hashlib.sha256(data).hexdigest(); blob=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
 assert sha==row['sha256'] and len(data)==row['bytes'] and blob==tree[row['catalogKey']+'.nlogox']['sha']==row['galapagos']['blobSha1']
 root=E.fromstring(data); dest=Path('experiments')/slug; dest.mkdir(exist_ok=True); (dest/'source.nlogox').write_bytes(data)
 provenance={k:row[k] for k in ['id','sourceUrl','sha256','bytes','gitBlobSha1','galapagos','netlogoVersion','extensions','includes']}
 (dest/'source.json').write_text(json.dumps(provenance,indent=2)+'\n')
 (dest/'NOTICE.md').write_text(f"# {row['name']} provenance\n\nCanonical selected path: `{row['id']}`.\n\nExact served source: {row['sourceUrl']}\n\nSHA-256 `{sha}`; {len(data)} bytes; Git blob `{blob}`. Pinned Galapagos `{inv['upstream']['galapagos']}`.\n\n## Citation\n\n{row.get('citationNotice','')}\n\n## Credits\n\n{row.get('creditsNotice','')}\n\n## Copyright and license\n\n{row['licenseNotice']}\n\n## Adaptation\n\nReadable headless TypeScript composition using public City Library operations; independent Mulberry RNG, no cross-engine seeded trajectory identity. Native source is retained unchanged. Procedure/order and browser adaptations are tracked in selected-materials reports. Research is not empirical validation.\n")
 report += [f"## {row['name']}",'',f"Canonical path: `{row['id']}`. Source URL: {row['sourceUrl']}. SHA-256 `{sha}`; bytes {len(data)}; Git blob `{blob}`. Includes `{row['includes']}`; extensions `{row['extensions']}`.",'','### Binding semantic audit','',notes[slug],'','### Exact widgets, defaults, plots and actions','', '```xml',E.tostring(root.find('widgets'),encoding='unicode'),'```','','### Exact named procedures and equations','','```netlogo',root.findtext('code'),'```','']
 evidence.append({'slug':slug,**provenance,'archiveMatchesInventoryAndPinnedBlob':True})
Path('docs/development/selected-materials-source-audit.md').write_text('\n'.join(report))
Path('docs/development/selected-materials-evidence/source-validation.json').write_text(json.dumps(evidence,indent=2)+'\n')
print('Validated and archived',len(evidence),'exact XML originals')
